function freshState() {
  return {
    name: '', capital: { cash: 0, account: 0 }, incomes: [], expenses: [], debts: [],
    transactions: [], spendingPeriods: [], mode: 'common', targetMonths: 18,
    onboarded: false, profileConfigured: false, capitalConfigured: false,
    capitalMode: 'split', goalEnabled: false, goalMonths: null, goalDate: null, selectedPlanId: null,
    accumulationPlans: [],
    useCapitalAdvance: false, capitalAdvanceConfirmed: false, capitalAdvanceAmount: 0
  };
}

const savedState = JSON.parse(localStorage.getItem('rientro-state') || 'null');
let state = savedState || freshState();
if (!state.spendingPeriods) state.spendingPeriods = [];
if (!Array.isArray(state.incomes)) state.incomes=[];
if (!Array.isArray(state.expenses)) state.expenses=[];
if(!Array.isArray(state.accumulationPlans)){state.accumulationPlans=state.accumulationEnabled?[{id:Date.now(),name:state.accumulationName||'Il mio obiettivo',target:Number(state.accumulationTarget)||0,months:Number(state.accumulationMonths)||12,current:Number(state.accumulationCurrent)||0,priority:1}]:[];save()}
if (savedState && typeof state.capitalConfigured !== 'boolean') state.capitalConfigured=false;
if (savedState && (!state.profileConfigured || state.name === 'Giulia')) state.profileConfigured = false;
if(savedState && Number(state.logicVersion||0)<2){
  const removedIds=new Set((state.transactions||[]).filter(item=>item.automatic).map(item=>String(item.id)));
  state.transactions=(state.transactions||[]).filter(item=>!item.automatic);
  state.spendingPeriods=(state.spendingPeriods||[]).map(period=>({...period,entries:(period.entries||[]).filter(item=>!removedIds.has(String(item.transactionId)))}));
  state.logicVersion=2;save();
}
if(savedState&&state.capitalConfigured&&!state.capitalAsOf){const today=new Date();state.capitalAsOf=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;state.logicVersion=3;save()}
let view = state.onboarded ? (state.profileConfigured === false ? 'profile' : 'dashboard') : 'onboarding';
let onboardingStep = 0;
let deferredInstallPrompt = null;
let comparingPlans = false;
const app = document.querySelector('#app');
const icons = {
  home: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11.5 12 4l9 7.5M5.5 10v10h13V10M9.5 20v-6h5v6"/></svg>',
  plan: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 20V10m7 10V4m7 16v-7M3 20h18"/></svg>',
  move: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h10M4 17h13"/><path d="m17 14 3 3-3 3"/></svg>',
  analysis: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19V9m5 10V5m5 14v-7m5 7V3M2 19h20"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
  info: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.5"/></svg>',
  wallet: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7.5h15a2 2 0 0 1 2 2v9H5a2 2 0 0 1-2-2v-11a2 2 0 0 1 2-2h12v4M16 13h5"/></svg>'
};

function save(){ localStorage.setItem('rientro-state', JSON.stringify(state)); }
function toast(message){ const el=document.querySelector('#toast'); el.textContent=message; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2200); }
function syncSpendingEntry(transaction){
  if(!state.spendingPeriods.length) state.spendingPeriods=[{label:'Periodo attuale',entries:[]}];
  const entries=state.spendingPeriods[0].entries ||= [];
  state.spendingPeriods[0].entries=entries.filter(entry=>String(entry.transactionId)!==String(transaction.id));
  const future=transaction.recordedAt&&new Date(`${transaction.recordedAt}T12:00:00`)>new Date();
  if(transaction.type==='expense'&&!transaction.planKind&&!future) state.spendingPeriods[0].entries.push({transactionId:transaction.id,label:transaction.label,amount:transaction.amount,category:transaction.category||'Altro'});
}
function syncDueSpendingEntries(){(state.transactions||[]).forEach(syncSpendingEntry)}
function shell(content, active='dashboard') {
  return `<div class="shell"><aside class="sidebar">
    <a class="brand" href="#" data-view="dashboard"><span class="brand-mark">R</span><span>Rientro</span></a>
    <nav aria-label="Navigazione principale">
      ${navItem('dashboard','home','Oggi',active)}${navItem('plan','plan','Il mio piano',active)}${navItem('transactions','move','Movimenti',active)}${navItem('analysis','analysis','Analisi spese',active)}
    </nav>
    <button class="nav-item settings-link" data-settings>Impostazioni</button><div class="sidebar-note"><span>Solo sul tuo dispositivo</span><p>Nessun conto collegato. I tuoi dati restano in questo browser.</p></div>
  </aside><main><button class="ios-settings" data-settings aria-label="Apri impostazioni">${icons.info}</button>${content}</main>${mobileNav(active)}</div>`;
}
function navItem(id, icon, label, active){ return `<button class="nav-item ${active===id?'active':''}" data-view="${id}">${icons[icon]}<span>${label}</span></button>`; }
function mobileNav(active){return `<nav class="mobile-nav" aria-label="Navigazione principale">${navItem('dashboard','home','Oggi',active)}${navItem('plan','plan','Piano',active)}<button class="nav-item add-mobile" data-add aria-label="Aggiungi movimento">${icons.plus}<span>Aggiungi</span></button>${navItem('transactions','move','Movimenti',active)}${navItem('analysis','analysis','Analisi',active)}</nav>`}
function header(kicker,title,action=''){return `<header class="page-header"><div><span class="kicker">${kicker}</span><h1>${title}</h1></div>${action}</header>`}
function frequencyLabel(value){return ({weekly:'settimana',monthly:'mese',quarterly:'trimestre',yearly:'anno'})[value]||'mese'}
function capitalFields(prefix=''){const split=state.capitalMode==='split';return `<fieldset class="capital-choice"><legend>Come vuoi indicarlo?</legend><div class="type-toggle"><label><input type="radio" name="capitalMode" value="total" ${split?'':'checked'}><span>Totale unico</span></label><label><input type="radio" name="capitalMode" value="split" ${split?'checked':''}><span>Dividi conto e contanti</span></label></div><div class="capital-total-fields"><label>Capitale totale<div class="money-input"><b>€</b><input name="total" type="number" min="0" step="1" value="${state.capitalConfigured&&!split?state.capital.account:''}" placeholder="0"></div></label></div><div class="capital-split-fields"><label>Conto<div class="money-input"><b>€</b><input name="account" type="number" min="0" step="1" value="${state.capitalConfigured?state.capital.account:''}" placeholder="0"></div></label><label>Contanti<div class="money-input"><b>€</b><input name="cash" type="number" min="0" step="1" value="${state.capitalConfigured?state.capital.cash:''}" placeholder="0"></div></label><small>Il totale sarà la somma esatta di conto e contanti.</small></div></fieldset><p class="capital-explainer">È la fotografia di ciò che hai oggi. Le scadenze precedenti a questa fotografia sono considerate già comprese nel saldo e non vengono sottratte di nuovo.</p><p class="form-error" hidden></p>`}

function dashboard(){
  const p=calculatePlan(state), activeDebt=selectedDebtPlan(state), savings=accumulationPlans(state), savingTotal=savings.reduce((sum,item)=>sum+item.monthlyRate,0), capital=totalCapital(state), balances=capitalBalances(state), pace=spendingPace(state), forecast=accountForecast(state), insight=spendingPaceInsight(state), timeline=monthlyTimeline(state), progress=Math.min(100, Math.round((1-p.debtTotal/8200)*100));
  const futureTimeline=timeline.filter(item=>item.status==='planned'&&item.day>=new Date().getDate()).slice(0,6);
  const todayLabel=new Intl.DateTimeFormat('it-IT',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
  return shell(`${header(todayLabel.charAt(0).toUpperCase()+todayLabel.slice(1),`Buongiorno, ${state.name}.`,`<div class="header-actions"><button class="button secondary" data-capital>Imposta capitale</button><button class="button secondary desktop-only" data-add>${icons.plus} Aggiungi</button></div>`)}
    ${!state.capitalConfigured?`<section class="capital-banner"><div><span class="eyebrow">Quando vuoi</span><h2>Inserisci quanto hai oggi</h2><p>È una fotografia del saldo attuale. Puoi indicare conto e contanti adesso oppure farlo più avanti.</p></div><button class="button" data-capital>Inserisci saldo</button></section>`:''}
    <section class="capital-hero reveal"><div><p class="eyebrow">Capitale disponibile</p><div class="capital-value">${state.capitalConfigured?money(capital):'Da impostare'}</div>${state.capitalConfigured?`<details class="forecast-disclosure"><summary>Apri previsione conto</summary><div class="capital-detail account-forecast"><div class="forecast-balances"><span>Conto oggi <b>${money(balances.account)}</b></span><span>Contanti oggi <b>${money(balances.cash)}</b></span></div>${forecast?`<div class="forecast-ledger"><p><span>Entrate prima dello stipendio</span><b>+ ${money(forecast.upcomingIncome)}</b></p><p><span>Spese programmate da pagare</span><b>− ${money(forecast.upcomingExpenses)}</b></p><p><span>Rate ancora da accantonare</span><b>− ${money(forecast.debtSetAside)}</b></p><p><span>Obiettivi ancora da accantonare</span><b>− ${money(forecast.savingSetAside)}</b></p></div><div class="forecast-result"><span>Prima delle spese quotidiane</span><strong>${money(forecast.totalBeforeDaily)}</strong><small>Se rispetti il ritmo indicato, al prossimo stipendio restano circa <b>${money(forecast.endComfort)}</b> di margine protetto.</small></div><p class="forecast-assumption">Il saldo è una fotografia del ${state.capitalAsOf?new Date(`${state.capitalAsOf}T12:00:00`).toLocaleDateString('it-IT',{day:'numeric',month:'long'}):'giorno in cui lo hai inserito'}: le scadenze precedenti sono già comprese. I contanti restano separati.</p>`:'<p class="forecast-assumption">Aggiungi il giorno dello stipendio per vedere la previsione completa.</p>'}</div></details>`:`<button class="text-button" data-capital>Inserisci il saldo reale</button>`}</div>
      <div class="calm-note"><span class="pulse"></span><p>${state.capitalConfigured&&state.incomes.length?`<strong>Il piano si adatta alla tua vita.</strong><br>La quota debiti di questo ciclo è ${money(activeDebt?.rate||0)}; dopo spese e quota restano ${money(activeDebt?.livingMoney||p.freeCash)} per vivere e gestire gli imprevisti.`:`<strong>Comincia con calma.</strong><br>Aggiungi saldo ed entrata quando vuoi: fino ad allora non mostriamo stime incomplete.`}</p></div></section>
    <section class="metric-strip reveal"><div><span>Entrate mensili</span><strong>${money(p.income)}</strong></div><div><span>Uscite previste</span><strong>${money(p.expenses)}</strong></div><div><span>Libero dopo le spese</span><strong>${money(p.freeCash)}</strong></div></section>
    ${pace.available?`<section class="pace-card reveal"><div class="pace-heading"><div><span class="eyebrow">Ritmo fino al prossimo accredito</span><h2>${pace.mainIncome.name||'Entrata principale'} · ${pace.payday.toLocaleDateString('it-IT',{day:'numeric',month:'long'})}${pace.estimatedPayday?' (stima)':''}</h2><p>È la cifra spendibile dopo aver già protetto spese, piani scelti e margine di fine mese.</p></div><span class="pace-status"><i></i>Ricalcolo automatico</span></div><div class="pace-values"><div><span>Puoi spendere al giorno</span><strong>${money(pace.daily)}</strong></div><div><span>Puoi spendere in 7 giorni</span><strong>${money(pace.weekly)}</strong></div></div>${insight?`<div class="pace-insight ${insight.delta<0?'down':insight.delta>0?'up':''}"><span>↳</span><p><strong>Cosa è cambiato</strong>${insight.text}</p></div>`:''}<details class="pace-details"><summary>Come abbiamo calcolato questa cifra?</summary><div><p><span>Capitale dopo tutti i movimenti</span><b>${money(pace.liquidNow)}</b></p>${pace.upcomingIncome?`<p><span>Altre entrate prima dell’accredito</span><b>+ ${money(pace.upcomingIncome)}</b></p>`:''}<p><span>Spese programmate ancora da pagare</span><b>− ${money(pace.upcomingExpenses)}</b></p><p><span>Rata del piano ancora da accantonare</span><b>− ${money(pace.debtSetAside)}</b></p>${pace.savingSetAside?`<p><span>Risparmio ancora da accantonare</span><b>− ${money(pace.savingSetAside)}</b></p>`:''}<p><span>Margine protetto per il fine mese</span><b>− ${money(pace.comfortMargin)}</b></p><p class="pace-total"><span>Disponibile reale fino all’accredito</span><b>${money(pace.spendable)}</b></p></div></details></section>`:`<section class="pace-card pace-empty"><div><span class="eyebrow">Ritmo di spesa</span><h2>${pace.reason==='capital'?'Imposta il capitale reale':'Aggiungi un’entrata ricorrente'}</h2><p>Ci servono capitale ed entrata principale per calcolare quanto puoi spendere fino al prossimo accredito.</p></div><button class="button secondary" ${pace.reason==='capital'?'data-capital':'data-view="transactions"'}>Completa i dati</button></section>`}
    <section class="month-roadmap reveal"><div class="section-head"><div><span class="eyebrow">Prossime date</span><h2>Solo ciò che viene dopo</h2></div><small>${futureTimeline.length?`${futureTimeline.length} in programma`:'Tutto aggiornato'}</small></div><div class="roadmap-list">${futureTimeline.length?futureTimeline.map(item=>`<div class="roadmap-item planned"><span class="roadmap-day"><b>${item.day}</b><small>${new Intl.DateTimeFormat('it-IT',{month:'short'}).format(new Date())}</small></span><i class="${item.type}"></i><div class="grow"><strong>${item.label}</strong><span>${item.type==='income'?'Entrata attesa':item.type==='saving'?'Accumulo programmato':item.type==='debt'?'Rata protetta':'Uscita prevista'}</span></div><b class="roadmap-amount ${item.type}">${item.type==='income'?'+':'−'} ${money(item.amount)}</b></div>`).join(''):'<div class="smart-empty"><span>✓</span><div><strong>Nessuna scadenza davanti a te</strong><p>Le voci passate sono già nei Movimenti. La Home mostrerà qui soltanto i prossimi impegni.</p></div></div>'}</div></section>
    <section class="plan-glance reveal"><div><span class="eyebrow">Piano flessibile</span><h2>${state.debts.length?`${activeDebt?.name||'Piano'} · ${money(activeDebt?.rate||0)} questo ciclo`:'Nessun piano di rientro'}${savings.length?` · ${savings.length} ${savings.length===1?'accumulo':'accumuli'}`:''}</h2><p>Si ricalcola con entrate e uscite, proteggendo prima i soldi per vivere.</p></div><button class="button secondary" data-view="plan">Gestisci i piani</button></section>
    <p class="disclaimer">Rientro offre stime per la pianificazione personale, non consulenza finanziaria o di investimento.</p>`,'dashboard');
}

function plan(){
 const p=calculatePlan(state); const scenarios=planScenarios(state); const chosen=selectedDebtPlan(state); const savings=accumulationPlans(state); const goal=evaluateGoal(state);
 const formula=b=>b.months?`<div class="plan-formula"><span>${money(b.rate)} × ${b.months} mesi</span>${b.advance?`<span>+ anticipo ${money(b.advance)}</span>`:''}<strong>Totale coperto ${money(b.totalCovered)}</strong>${b.rounding?`<small>Ultima rata ridotta di ${money(b.rounding)} per arrotondamento</small>`:b.residual?`<small>Residuo ${money(b.residual)}</small>`:'<small>Residuo 0 €</small>'}</div>`:'';
 const configureButton=`<button class="button" data-add-debt>${icons.plus} ${state.debts.length?'Aggiungi un debito':'Configura il mio piano'}</button>`;
 const savingSection=`<section class="saving-plans"><div class="section-head"><div><span class="eyebrow">Piani di accumulo</span><h2>Obiettivi in ordine di priorità</h2></div><button class="button secondary" data-accumulation>Nuovo obiettivo</button></div><p class="saving-intro">La quota disponibile viene assegnata prima agli obiettivi più importanti, senza intaccare il margine di fine mese.</p><div class="saving-plan-list">${savings.length?savings.map(saving=>`<article class="saving-section ${!saving.feasible?'saving-warning':''}"><div class="priority-tag">${saving.priority}</div><div class="grow"><span class="eyebrow">Priorità ${saving.priority}</span><h2>${saving.name}</h2><p>${saving.feasible?`Quota ${money(saving.monthlyRate)} al mese · circa ${saving.estimatedMonths||saving.months} mesi.`:saving.monthlyRate?`Riceve ${money(saving.monthlyRate)} al mese; serviranno circa ${saving.estimatedMonths} mesi.`:'In attesa: il margine disponibile è già assegnato agli obiettivi precedenti.'}<span class="progress-copy"><b>${money(saving.accumulated)}</b> accumulati su ${money(saving.totalTarget)}</span><span class="progress-track"><i style="--progress:${saving.progress}%"></i></span></p></div><div class="saving-actions"><button class="text-button" data-accumulation="${saving.id}">Modifica</button>${saving.progress<100?`<button class="button" data-contribute="saving" data-target-id="${saving.id}">Registra versamento</button>`:''}</div></article>`).join(''):'<div class="saving-section"><div class="saving-symbol">↗</div><div class="grow"><h2>Costruisci un obiettivo, senza arrivare corto</h2><p>Puoi creare più obiettivi e decidere quali vengono prima.</p></div><button class="button" data-accumulation>Crea il primo</button></div>'}</div></section>`;
 return shell(`${header('I tuoi piani','Una strada che puoi seguire.',configureButton)}
  ${!state.debts.length?`<section class="debt-empty"><span class="empty-icon">${icons.plan}</span><span class="eyebrow">Inizia da qui</span><h2>Crea il tuo piano di rientro</h2><p>Aggiungi uno o più debiti. Bastano nome e importo residuo; rata minima e obiettivo restano facoltativi.</p><button class="button" data-add-debt>${icons.plus} Aggiungi il primo debito</button></section>`:`
  <p class="debt-count">${state.debts.length===1?'1 debito presente':`${state.debts.length} debiti presenti`} · totale ${money(p.debtTotal)}</p><section class="plan-summary ${chosen.feasible?'':'warning'}"><div><span class="eyebrow">Quota flessibile di questo ciclo</span><strong>${chosen.feasible?money(chosen.rate):'—'}</strong><span>${chosen.feasible?`Stima attuale: circa ${chosen.months} mesi`:'Le rate minime superano ciò che resta davvero disponibile'}</span>${chosen.feasible?formula(chosen.breakdown):''}</div><div class="why"><span>${icons.info}</span><p><strong>${chosen.feasible?'Perché proprio questa cifra?':'Perché non c’è ancora una proposta?'}</strong> ${chosen.feasible?`Dopo le spese fisse parti da ${money(p.freeCash)}. ${chosen.occasionalExpenses?`Le uscite occasionali del ciclo (${money(chosen.occasionalExpenses)}) hanno abbassato la quota. `:''}${chosen.extraIncome?`Delle entrate extra (${money(chosen.extraIncome)}) solo una parte va ai debiti. `:''}Restano ${money(chosen.livingMoney)} per vivere e gestire gli imprevisti. Il saldo iniziale non viene considerato un’entrata extra.`:`Le rate minime sono ${money(p.minimumPayments)}, ma il piano protegge prima le spese già inserite e il denaro necessario per il ciclo.`}</p></div></section>
  <section class="goal-section ${goal&&!goal.feasible?'goal-warning':''}"><div><div><span class="eyebrow">Il tuo obiettivo</span><h2>${goal?`${goal.label} entro ${goal.months} mesi`:'Vuoi indicare una scadenza?'}</h2><p>${goal?(goal.feasible?`Servirebbero circa ${money(goal.necessaryRate)} al mese, con ${money(goal.margin)} di margine.`:goal.extensionMonths?`Per proteggere spese essenziali e riserva, estendi di ${goal.extensionMonths} mesi fino a circa ${goal.recommendedMonths} mesi, con ${money(goal.recommendedRate)} al mese.`:`Con il budget attuale non emerge ancora una durata sostenibile.`):'Puoi scegliere una durata o una data. Senza obiettivo, resta valida la proposta automatica.'}</p>${goal?formula(goal.breakdown):''}</div><button class="button secondary" data-goal>${goal?'Modifica obiettivo':'Imposta obiettivo'}</button></div></section>
  <section class="advance-control"><div><span class="eyebrow">Capitale iniziale</span><h2>${state.capitalConfigured?`${money(p.availableCapital)} totali · ${p.capitalForDebt?`anticipo ${money(p.capitalForDebt)}`:'non usati'}`:'Totale reale da impostare'}</h2><p>Il totale unico è il riferimento principale. Per default il piano usa solo gli accantonamenti mensili.</p></div><button class="text-button" ${state.capitalConfigured?'data-advance':'data-capital'}>${state.capitalConfigured?(p.capitalForDebt?'Modifica anticipo':'Valuta un anticipo'):'Imposta capitale'}</button></section>
  ${!p.feasible?`<section class="alternative budget-alert"><span class="eyebrow">Un passo realistico</span><h2>Prima riduci la pressione mensile</h2><p>Puoi verificare le spese variabili oppure confrontare una durata maggiore. Se le rate minime restano sopra il margine disponibile, valuta direttamente con i creditori se esistono condizioni diverse. Nessuna quota sotto le rate minime viene presentata come sostenibile.</p></section>`:''}
  <section class="scenario-section ${state.selectedPlanId&&!comparingPlans?'has-choice':''}"><div class="section-head"><div><span class="eyebrow">${state.selectedPlanId&&!comparingPlans?'Regola flessibile attiva':'Scegli quanta elasticità vuoi'}</span><h2>${state.selectedPlanId&&!comparingPlans?`${chosen.name} · oggi suggerisce ${money(chosen.rate)}`:'Prudente, Bilanciato o Veloce'}</h2></div>${state.selectedPlanId&&!comparingPlans?'<button class="text-button" data-change-plan>Cambia regola</button>':'<small>La cifra cambierà, la regola resterà la stessa</small>'}</div><div class="scenario-grid">${scenarios.filter(s=>!state.selectedPlanId||comparingPlans||s.id===state.selectedPlanId).map(s=>`<article class="scenario ${s.id===state.selectedPlanId||(!state.selectedPlanId&&s.recommended)?'featured':''} ${s.feasible?'':'unavailable'}"><div class="scenario-title"><span>${s.name}</span>${s.id===state.selectedPlanId?'<em>Attivo</em>':s.recommended?'<em>Consigliato</em>':''}</div><strong>${s.feasible?money(s.rate):'Non sostenibile'}${s.feasible?'<small> questo ciclo</small>':''}</strong><dl><div><dt>Resta per vivere</dt><dd>${s.livingMoney===null?'—':money(s.livingMoney)}</dd></div><div><dt>Durata stimata</dt><dd>${s.months?`${s.months} mesi`:'—'}</dd></div></dl>${s.feasible?formula(s.breakdown):''}${s.feasible&&s.id!==state.selectedPlanId?`<button class="button scenario-choose" data-select-plan="${s.id}">Scegli ${s.name}</button>`:''}${s.recommended&&!state.selectedPlanId?'<p>Destina il 35% del libero ai debiti e lascia il resto alla vita quotidiana.</p>':!s.feasible?'<p>Le rate minime superano il disponibile reale del ciclo.</p>':''}</article>`).join('')}</div><p class="estimate-note">Ogni entrata o uscita ricalcola la quota. Le stime non includono interessi o penali non inseriti.</p></section>
  <section class="journey"><div class="section-head"><div><span class="eyebrow">I debiti inseriti</span><h2>Dati usati nel calcolo</h2></div><button class="text-button" data-add-debt>Aggiungi</button></div>${state.debts.map((d,i)=>{const original=Math.max(Number(d.originalBalance)||0,Number(d.balance)||0),paid=Math.max(0,original-Number(d.balance)),progress=original?Math.round(paid/original*100):0;return `<div class="debt-step"><span class="step-dot">${i+1}</span><div class="grow"><div class="debt-title"><strong>${d.name}</strong><b>${money(d.balance)} residui</b></div>${d.originalBalance?`<span class="progress-copy"><b>${money(paid)}</b> rimborsati su ${money(original)}</span><span class="progress-track"><i style="--progress:${progress}%"></i></span>`:''}<div class="debt-meta"><span>Rata minima ${d.minimumPayment?money(d.minimumPayment):'non indicata'}</span><span>${d.targetDate?`Obiettivo: ${new Date(`${d.targetDate}T12:00:00`).toLocaleDateString('it-IT',{month:'long',year:'numeric'})}`:d.months?`Obiettivo: ${d.months} mesi`:'Nessun obiettivo individuale'}</span></div><p>${d.months||d.targetDate?'Questo obiettivo viene valutato insieme al budget e alle altre rate.':'La proposta automatica funziona anche senza una scadenza.'}</p><div class="debt-actions"><button data-contribute="debt" data-target-id="${d.id}">Registra pagamento</button><button data-edit-debt="${d.id}">Modifica</button><button class="danger-link" data-remove-debt="${d.id}">Rimuovi</button></div></div></div>`}).join('')}</section>
  <section class="reserve"><div>${icons.wallet}<div><span class="eyebrow">Riserva suggerita</span><h2>${money(p.reserveTarget)}</h2></div></div><p>Corrisponde a due mesi delle tue spese essenziali (${money(p.essential)}/mese). Serve a non ricorrere a nuovo debito davanti a un imprevisto.</p></section>
  <p class="disclaimer">Queste sono stime di pianificazione personale. Non includono interessi o penali non inseriti e non sono consulenza finanziaria.</p>`}
  ${savingSection}`,'plan');
}

function transactions(){
 const periodLabel=new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date());
 const registeredTotal=state.transactions.filter(t=>!t.recordedAt||new Date(`${t.recordedAt}T12:00:00`)<=new Date()).reduce((sum,t)=>sum+(t.type==='income'?1:-1)*t.amount,0);
 return shell(`${header('Movimenti','Ogni cifra, al suo posto.',`<button class="button secondary desktop-only" data-add>${icons.plus} Aggiungi</button>`)}
 <section class="transactions"><div class="section-head"><div><span class="eyebrow">${periodLabel.charAt(0).toUpperCase()+periodLabel.slice(1)}</span><h2>Registrati e futuri</h2></div><strong>${money(registeredTotal)}</strong></div>
 <div class="list">${state.transactions.length?state.transactions.map(t=>{const future=t.recordedAt&&new Date(`${t.recordedAt}T12:00:00`)>new Date();const status=future?`Previsto · ${new Date(`${t.recordedAt}T12:00:00`).toLocaleDateString('it-IT',{day:'numeric',month:'short'})}`:`Registrato · ${t.recordedAt?new Date(`${t.recordedAt}T12:00:00`).toLocaleDateString('it-IT',{day:'numeric',month:'short'}):t.date}`;return `<div class="list-row transaction ${future?'future-transaction':''}"><span class="transaction-icon ${t.type}">${t.type==='income'?'↓':'↑'}</span><div class="grow"><strong>${t.label}</strong><span>${status} · ${t.channel==='cash'?'contanti':t.type==='income'?'bonifico/accredito':'bancomat o carta'}${t.planKind?' · dal Piano':''}</span></div><div class="movement-value"><b class="${t.type}">${t.type==='income'?'+':'−'} ${money(t.amount)}</b>${t.planKind?'':`<span><button data-edit-movement="${t.id}">Modifica</button><button class="danger-link" data-remove-movement="${t.id}">Elimina</button></span>`}</div></div>`}).join(''):`<div class="empty"><h2>Ancora nessun movimento occasionale</h2><p>Le voci fisse sono gestite separatamente qui sotto.</p><button class="button" data-add>Aggiungi</button></div>`}</div></section>
 <section class="recurring-section"><div class="section-head"><div><span class="eyebrow">Budget mensile</span><h2>Entrate e spese fisse</h2></div><button class="text-button" data-add-recurring="income">Aggiungi voce</button></div><p class="recurring-intro">Queste voci alimentano automaticamente budget, riserva e rata consigliata. I movimenti occasionali restano separati.</p><div class="recurring-groups">${recurringGroup('Entrate fisse',state.incomes,'income')}${recurringGroup('Spese fisse',state.expenses,'expense')}</div><p class="disclaimer">Le rate minime dei debiti restano nel Piano e non vengono duplicate. Inserisci qui solo rate esterne non già comprese nei debiti.</p></section>`,'transactions');
}

function recurringGroup(title,items,type){return `<div><div class="recurring-title"><h3>${title}</h3><button data-add-recurring="${type}">${icons.plus}</button></div>${items.length?items.map(item=>`<article class="recurring-row"><div><strong>${item.name}</strong><span>${money(item.amount)} ogni ${frequencyLabel(item.frequency)}${item.due?` · giorno ${item.due}`:''}</span><small>Previsione mensile ${money(monthlyAmount(item))}</small></div><div><button data-edit-recurring="${type}:${item.id}">Modifica</button><button class="danger-link" data-remove-recurring="${type}:${item.id}">Rimuovi</button></div></article>`).join(''):'<p class="muted-empty">Nessuna voce inserita.</p>'}</div>`}

function analysis(){
 syncDueSpendingEntries();
 const result=spendingAnalysis(state.spendingPeriods), max=result.highest?.amount || 1;
 const pace=spendingPace(state);
 const direction=result.changePercentage===0?'in linea con':result.changePercentage<0?'più basse di':'più alte di';
 const change=Math.abs(result.changePercentage || 0), entries=state.spendingPeriods[0]?.entries || [];
 const fixed=state.expenses.filter(x=>x.kind==='fixed'||(x.essential&&!x.kind)).reduce((sum,x)=>sum+monthlyAmount(x),0);
 const variable=state.expenses.filter(x=>x.kind==='variable'||(!x.essential&&!x.kind)).reduce((sum,x)=>sum+monthlyAmount(x),0);
 const debtRates=state.debts.reduce((sum,x)=>sum+Math.max(Number(x.minimumPayment)||0,Math.ceil(Number(x.balance)/Math.max(1,Number(x.months)||18))),0);
 return shell(`${header('Analisi','Capisci oggi, decidi con calma.')}
 ${pace.available?`<section class="spendable-analysis reveal"><div class="spendable-top"><div><span class="eyebrow light">Disponibile reale</span><h2>Puoi spendere fino al prossimo stipendio</h2></div><span class="live-indicator"><i></i>Si aggiorna subito</span></div><strong class="spendable-total">${money(pace.spendable)}</strong><p class="spendable-until">Fino al ${pace.payday.toLocaleDateString('it-IT',{day:'numeric',month:'long'})} · circa <b>${money(pace.daily)} al giorno</b> oppure <b>${money(pace.weekly)} in 7 giorni</b>.</p><div class="spendable-breakdown"><p><span>Saldo disponibile oggi</span><b>${money(pace.liquidNow)}</b></p><p><span>Entrate previste prima dello stipendio</span><b>+ ${money(pace.upcomingIncome)}</b></p><p><span>Spese previste e programmate</span><b>− ${money(pace.upcomingExpenses)}</b></p><p><span>Debiti da accantonare</span><b>− ${money(pace.debtSetAside)}</b></p><p><span>Accumuli da accantonare</span><b>− ${money(pace.savingSetAside)}</b></p><p><span>Margine protetto</span><b>− ${money(pace.comfortMargin)}</b></p></div><small>Le entrate future aiutano la previsione, ma non aumentano il saldo finché non arriva la loro data.</small></section>`:`<section class="spendable-analysis spendable-empty reveal"><div><span class="eyebrow light">Quanto puoi spendere</span><h2>${pace.reason==='capital'?'Inserisci prima il saldo attuale':'Aggiungi lo stipendio e il giorno di accredito'}</h2><p>Appena ci sono questi due dati, calcoliamo il disponibile al netto di spese, debiti, accumuli e movimenti futuri.</p></div><button class="button light-button" ${pace.reason==='capital'?'data-capital':'data-add-recurring="income"'}>Completa i dati</button></section>`}
 <section class="analysis-hero reveal"><div><span class="eyebrow light">Totale · ${result.currentLabel}</span><strong>${money(result.total)}</strong><p>Le spese sono <b>${change}% ${direction}</b> ${result.previousLabel}. È solo un confronto: serve a orientarti, non a dare giudizi.</p></div><div class="comparison"><span>Periodo precedente</span><strong>${money(result.previousTotal)}</strong><small>${result.changePercentage>0?'↑':result.changePercentage<0?'↓':'→'} ${change}% nel periodo attuale</small></div></section>
 <section class="expense-types" aria-label="Tipi di spesa mensile"><div><span><i class="fixed"></i>Spese fisse</span><strong>${money(fixed)}</strong></div><div><span><i class="variable"></i>Spese variabili</span><strong>${money(variable)}</strong></div><div><span><i class="debt"></i>Rate e debiti</span><strong>${money(debtRates)}</strong><small>quota mensile stimata</small></div></section>
 <div class="analysis-grid"><section class="paper-section reveal"><div class="section-head"><div><span class="eyebrow">Distribuzione</span><h2>Dove vanno le spese</h2></div><span class="period-label">${result.currentLabel}</span></div>
 <div class="category-chart" role="img" aria-label="Grafico delle spese per categoria">${result.categories.map((category,index)=>`<div class="chart-row"><div class="chart-label"><span>${category.name}</span><b>${money(category.amount)}</b></div><div class="chart-track"><i style="--size:${Math.round(category.amount/max*100)}%;--delay:${index*.05}s"></i></div><small>${category.percentage}% del totale</small></div>`).join('')}</div></section>
 <aside class="insight-card reveal"><span class="eyebrow light">In breve</span><h2>${result.highest?.name || 'Nessuna spesa'} è la voce principale</h2><p>${result.highest?`Incide per il ${result.highest.percentage}% (${money(result.highest.amount)}). Rispetto a ${result.previousLabel}, è ${result.highest.amount===result.highest.previousAmount?'stabile':result.highest.amount>result.highest.previousAmount?`aumentata di ${money(result.highest.amount-result.highest.previousAmount)}`:`diminuita di ${money(result.highest.previousAmount-result.highest.amount)}`}.`:'Aggiungi dei movimenti per iniziare a leggere le tue abitudini.'}</p><div class="expense-legend"><span><i class="fixed"></i>Fisse</span><span><i class="variable"></i>Variabili</span><span><i class="debt"></i>Rate e debiti</span></div><div class="insight-divider"></div><p class="gentle-copy">Non esiste una distribuzione “giusta” in assoluto. Puoi usare questi numeri per capire cosa è stabile e cosa cambia nel tempo.</p></aside></div>
 <section class="paper-section detail-section reveal"><div class="section-head"><div><span class="eyebrow">Voci e prodotti</span><h2>Cosa compone ogni categoria</h2></div></div><div class="category-details">${result.categories.map((category,index)=>`<details ${index===0?'open':''}><summary><span><i class="category-dot"></i>${category.name}</span><span><b>${money(category.amount)}</b><small>${category.percentage}%</small></span></summary><div>${entries.filter(entry=>entry.category===category.name).sort((a,b)=>b.amount-a.amount).map(entry=>`<p><span>${entry.label}</span><b>${money(entry.amount)}</b></p>`).join('')}</div></details>`).join('')}</div></section>
 <p class="disclaimer">L’analisi usa soltanto i dati che hai inserito e offre stime di pianificazione personale, non una valutazione delle tue scelte.</p>`,'analysis');
}

function onboarding(){
 app.innerHTML=`<div class="onboarding"><div class="onboarding-brand"><span class="brand-mark">R</span><span>Rientro</span></div><form id="onboarding-form"><span class="kicker">Benvenuto</span><h1>Partiamo solo dal tuo nome.</h1><p>Saldo, entrate, spese e piani sono tutti facoltativi. Li aggiungerai dalla Home, nel momento che preferisci.</p><div class="form-fields"><label>Come vuoi che ti chiamiamo?<input name="name" required maxlength="40" value="${state.name||''}" autocomplete="given-name" placeholder="Es. Andrea"></label></div><div class="form-actions"><button class="button" type="submit">Entra nell’app</button></div></form><div class="privacy-note">Nessun collegamento bancario. I dati restano in questo browser.</div></div>`;
}

function profileSetup(){ app.innerHTML=`<div class="onboarding"><div class="onboarding-brand"><span class="brand-mark">R</span><span>Rientro</span></div><form id="profile-form"><span class="kicker">Primo avvio</span><h1>Nome e capitale reale</h1><p>I dati demo già presenti non verranno cancellati. Prima di entrare nella dashboard, sostituisci il nome e il saldo di esempio.</p><div class="form-fields"><label>Il tuo nome<input name="name" required maxlength="40" value="${state.name || ''}" autocomplete="given-name" placeholder="Es. Andrea"></label>${capitalFields()}</div><div class="form-actions"><button class="button" type="submit">Salva e continua</button></div></form><div class="privacy-note">Nessun collegamento bancario. I dati restano sul dispositivo.</div></div>`; }

function settingsModal(){ return `<div class="modal-backdrop"><form class="modal settings-modal" id="settings-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Impostazioni</span><h2>Il tuo profilo</h2><label>Nome<input name="name" required maxlength="40" value="${state.name || ''}" autocomplete="given-name"></label><button class="button wide" type="submit">Salva nome</button><button class="text-button settings-capital" type="button" data-capital>Aggiorna capitale e ripartizione</button><section class="install-zone"><span class="eyebrow">Sul tuo telefono</span><p>Installa Rientro per aprirla dalla schermata Home, a tutto schermo e anche senza rete.</p><button class="button install-button" type="button" data-install-app>Installa Rientro</button></section><section class="reset-zone"><span class="eyebrow">Riparti da zero</span><p>Cancella capitale, movimenti, entrate, spese, debiti e obiettivi salvati su questo dispositivo.</p><button class="button reset-button" type="button" data-reset-all>Cancella tutti i dati</button></section></form></div>`; }

function resetAllModal(){ return `<div class="modal-backdrop"><div class="modal confirm-modal reset-confirm" role="dialog" aria-modal="true" aria-labelledby="reset-title"><span class="kicker">Conferma richiesta</span><h2 id="reset-title">Vuoi davvero ripartire da zero?</h2><p>Verranno eliminati definitivamente tutti i dati inseriti in Rientro su questo dispositivo:</p><ul><li>capitale e movimenti</li><li>entrate e spese ricorrenti</li><li>debiti, obiettivi e piano di rientro</li></ul><p class="reset-note">Questa operazione non può essere annullata.</p><div class="confirm-actions"><button class="button ghost" data-close>Annulla</button><button class="button danger" data-confirm-reset>Elimina e ricomincia</button></div></div></div>`; }

function capitalModal(){return `<div class="modal-backdrop"><form class="modal" id="capital-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Saldo reale</span><h2>Aggiorna il capitale</h2>${capitalFields()}<button class="button wide" type="submit" data-save-capital>Conferma capitale</button></form></div>`}

function addChoiceModal(){return `<div class="modal-backdrop"><div class="modal add-choice"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Aggiungi</span><h2>Cosa vuoi registrare?</h2><div class="choice-grid"><button data-add-occasional="income"><strong>Entrata occasionale</strong><span>Rimborso, regalo o accredito una tantum</span></button><button data-add-occasional="expense"><strong>Spesa occasionale</strong><span>Un acquisto o pagamento singolo</span></button><button data-add-recurring="income"><strong>Entrata fissa</strong><span>Stipendio, pensione o accredito periodico</span></button><button data-add-recurring="expense"><strong>Spesa fissa</strong><span>Affitto, bolletta, abbonamento o rata esterna</span></button></div></div></div>`}

function modal(defaultType='expense',transaction={}){const type=transaction.type||defaultType;const category=transaction.category||'Altro',now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;return `<div class="modal-backdrop"><form class="modal movement-modal ${type==='income'?'is-income':''}" id="movement-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">${transaction.id?'Modifica movimento':'Movimento occasionale'}</span><h2>${transaction.id?'Correggi il movimento':'Registra o programma'}</h2><input type="hidden" name="id" value="${transaction.id||''}"><div class="type-toggle"><label><input type="radio" name="type" value="expense" ${type==='expense'?'checked':''}><span>Spesa</span></label><label><input type="radio" name="type" value="income" ${type==='income'?'checked':''}><span>Entrata</span></label></div><label>Descrizione<input name="label" required value="${transaction.label||''}" placeholder="Es. Farmacia"></label><label>Data<input name="recordedAt" required type="date" value="${transaction.recordedAt||today}"><small>Se scegli una data futura, entra nella previsione senza cambiare subito il saldo.</small></label><label>Categoria<select name="category">${['Casa','Alimentari','Trasporti','Tempo libero','Salute','Altro'].map(x=>`<option ${x===category?'selected':''}>${x}</option>`).join('')}</select></label><label class="scheduled-match expense-match">Spesa programmata <span>opzionale</span><select name="expenseRecurringId"><option value="">Nessuna</option>${state.expenses.map(x=>`<option value="${x.id}" ${type==='expense'&&String(x.id)===String(transaction.recurringId)?'selected':''}>${x.name}</option>`).join('')}</select><small>Collega questa registrazione alla relativa previsione.</small></label><label class="scheduled-match income-match">Entrata programmata <span>opzionale</span><select name="incomeRecurringId"><option value="">Nessuna</option>${state.incomes.map(x=>`<option value="${x.id}" ${type==='income'&&String(x.id)===String(transaction.recurringId)?'selected':''}>${x.name}</option>`).join('')}</select><small>Collega questa registrazione alla relativa previsione.</small></label><label>Importo<div class="money-input"><b>€</b><input name="amount" required type="number" min="0.01" step="0.01" value="${transaction.amount||''}" placeholder="0,00"></div></label><fieldset class="channel-choice"><legend>Dove si muovono i soldi?</legend><label><input type="radio" name="channel" value="account" ${transaction.channel==='cash'?'':'checked'}><span><b data-channel-account>${type==='income'?'Bonifico o accredito':'Bancomat o carta'}</b><small>Aggiornerà il conto alla data scelta</small></span></label><label><input type="radio" name="channel" value="cash" ${transaction.channel==='cash'?'checked':''}><span><b>Contanti</b><small>Aggiornerà la cassa alla data scelta</small></span></label></fieldset><p class="form-error" hidden>Inserisci descrizione, data e importo.</p><button class="button wide" type="submit" data-save-movement>${transaction.id?'Salva modifiche':'Salva movimento'}</button></form></div>`; }

function removeMovementModal(transaction){return `<div class="modal-backdrop"><div class="modal confirm-modal" role="dialog" aria-modal="true" aria-labelledby="remove-movement-title"><span class="kicker">Elimina movimento</span><h2 id="remove-movement-title">Eliminare “${transaction.label}”?</h2><p>L’importo verrà riaccreditato al conto o ai contanti e le analisi saranno aggiornate.</p><div class="confirm-actions"><button class="button ghost" data-close>Annulla</button><button class="button danger" data-confirm-remove-movement="${transaction.id}">Elimina</button></div></div></div>`}

function recurringModal(type,item={}){const editing=Boolean(item.id);return `<div class="modal-backdrop"><form class="modal" id="recurring-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">${type==='income'?'Entrata fissa':'Spesa fissa'}</span><h2>${editing?'Modifica la voce':'Aggiungi una voce ricorrente'}</h2><input name="id" type="hidden" value="${item.id||''}"><input name="type" type="hidden" value="${type}"><label>Nome<input name="name" required value="${item.name||''}" placeholder="${type==='income'?'Es. Stipendio':'Es. Affitto'}"></label><label>Importo<div class="money-input"><b>€</b><input name="amount" required type="number" min="0.01" step="0.01" value="${item.amount||''}" placeholder="0"></div></label><label>Frequenza<select name="frequency"><option value="monthly" ${!item.frequency||item.frequency==='monthly'?'selected':''}>Mensile</option><option value="weekly" ${item.frequency==='weekly'?'selected':''}>Settimanale</option><option value="quarterly" ${item.frequency==='quarterly'?'selected':''}>Trimestrale</option><option value="yearly" ${item.frequency==='yearly'?'selected':''}>Annuale</option></select></label><label>Giorno previsto <span>opzionale</span><input name="due" type="number" min="1" max="31" value="${item.due||''}" placeholder="Es. 27"></label><p class="modal-copy">Serve per le previsioni. Non modifica il saldo: conto e contanti cambiano solo quando registri il movimento.</p>${type==='expense'?`<label class="confirm-check"><input name="essential" type="checkbox" ${item.essential?'checked':''}><span>È una spesa essenziale per la riserva</span></label><p class="modal-copy">Non inserire qui rate minime già associate ai debiti del Piano.</p>`:''}<p class="form-error" hidden>Controlla nome e importo.</p><button class="button wide" type="submit" data-save-recurring>${editing?'Salva modifiche':'Aggiungi al budget'}</button></form></div>`}

function debtModal(debt={}){ const editing=Boolean(debt.id); return `<div class="modal-backdrop debt-backdrop"><form class="modal debt-modal" id="debt-form" role="dialog" aria-modal="true" aria-labelledby="debt-modal-title"><header class="debt-modal-header"><div><span class="kicker">${editing?'Modifica debito':'Nuovo debito'}</span><h2 id="debt-modal-title">${editing?'Modifica il debito':'Aggiungi un debito'}</h2></div><button class="debt-close" type="button" data-close aria-label="Chiudi il modulo">Chiudi <span aria-hidden="true">×</span></button></header><div class="debt-open-cue" role="status"><span></span>Modulo aperto · completa i dati essenziali</div><div class="debt-modal-body"><input type="hidden" name="id" value="${debt.id || ''}"><label>Nome del debito<input name="name" required maxlength="60" value="${debt.name || ''}" placeholder="Es. Carta di credito"></label><label>Importo residuo<div class="money-input"><b>€</b><input name="balance" required type="number" min="1" step="1" value="${debt.balance || ''}" placeholder="2500"></div></label><label>Rata minima obbligatoria <span>opzionale se non esiste</span><div class="money-input"><b>€</b><input name="minimumPayment" type="number" min="0" step="1" value="${debt.minimumPayment || ''}" placeholder="90"></div></label><fieldset><legend>Preferenza personale <span>opzionale</span></legend><div class="objective-grid"><label>Durata da confrontare<input name="months" type="number" min="1" max="600" value="${debt.months || ''}" placeholder="18"></label><span>oppure</span><label>Data da confrontare<input name="targetDate" type="date" value="${debt.targetDate || ''}"></label></div><small>Non devi impostarla: la proposta automatica viene calcolata comunque.</small></fieldset><p class="form-error" hidden>Controlla nome e importo residuo.</p></div><footer class="debt-modal-footer"><button class="button wide" type="submit" data-save-debt>${editing?'Salva modifiche':'Aggiungi al piano'}</button></footer></form></div>`; }

function removeDebtModal(debt){ return `<div class="modal-backdrop"><div class="modal confirm-modal" role="dialog" aria-modal="true" aria-labelledby="remove-title"><span class="kicker">Rimuovi debito</span><h2 id="remove-title">Rimuovere ${debt.name}?</h2><p>Il debito non comparirà più nel piano e tutte le stime verranno aggiornate.</p><div class="confirm-actions"><button class="button ghost" data-close>Annulla</button><button class="button danger" data-confirm-remove="${debt.id}">Rimuovi</button></div></div></div>`; }

function goalModal(){ return `<div class="modal-backdrop"><form class="modal" id="goal-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Obiettivo complessivo</span><h2>Entro quando vuoi rientrare?</h2><p class="modal-copy">Indica una durata oppure una data per tutti i debiti. Calcoleremo la rata necessaria e, se serve, l’alternativa sostenibile più vicina.</p><label>Durata in mesi<input name="goalMonths" type="number" min="1" max="600" value="${state.goalEnabled&&state.goalMonths?state.goalMonths:''}" placeholder="Es. 6"></label><div class="field-separator">oppure</div><label>Data desiderata<input name="goalDate" type="date" value="${state.goalEnabled&&state.goalDate?state.goalDate:''}"></label><p class="form-error" hidden>Inserisci una durata o una data.</p><button class="button wide" type="submit">Valuta il mio obiettivo</button>${state.goalEnabled?'<button class="text-button remove-goal" type="button" data-clear-goal>Rimuovi obiettivo</button>':''}</form></div>`; }

function accumulationModal(id=''){const item=(state.accumulationPlans||[]).find(plan=>String(plan.id)===String(id))||{};return `<div class="modal-backdrop"><form class="modal" id="accumulation-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Piano di accumulo</span><h2>${item.id?'Modifica l’obiettivo':'Cosa vuoi mettere da parte?'}</h2><input name="id" type="hidden" value="${item.id||''}"><p class="modal-copy">Le priorità più basse ricevono spazio solo dopo quelle più importanti, conservando sempre un margine per il fine mese.</p><label>Nome dell’obiettivo<input name="name" required maxlength="60" value="${item.name||''}" placeholder="Es. Fondo imprevisti"></label><label>Somma da raggiungere<div class="money-input"><b>€</b><input name="target" required type="number" min="1" step="1" value="${item.target||''}" placeholder="Es. 2.000"></div></label><label>Tempo desiderato, in mesi<input name="months" required type="number" min="1" max="600" value="${item.months||''}" placeholder="Es. 12"></label><label>Priorità<select name="priority">${[1,2,3,4,5].map(value=>`<option value="${value}" ${Number(item.priority||state.accumulationPlans.length+1)===value?'selected':''}>${value} · ${value===1?'prima':value===2?'seconda':value===3?'terza':`${value}ª`}</option>`).join('')}</select></label><p class="form-error" hidden>Inserisci nome, somma e durata.</p><button class="button wide" type="submit">${item.id?'Salva modifiche':'Crea il piano di accumulo'}</button>${item.id?`<button class="text-button remove-goal" type="button" data-clear-accumulation="${item.id}">Rimuovi piano</button>`:''}</form></div>`}

function contributionModal(kind,targetId=''){const debt=kind==='debt'?state.debts.find(item=>String(item.id)===String(targetId)):null,saving=kind==='saving'?accumulationPlans(state).find(item=>String(item.id)===String(targetId)):null;const title=kind==='debt'?`Pagamento · ${debt?.name||'Debito'}`:`Versamento · ${saving?.name||'Accumulo'}`;const suggested=kind==='debt'?selectedDebtPlan(state)?.rate:saving?.monthlyRate;return `<div class="modal-backdrop"><form class="modal contribution-modal" id="contribution-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Aggiorna il progresso</span><h2>${title}</h2><input name="kind" type="hidden" value="${kind}"><input name="targetId" type="hidden" value="${targetId}"><label>Importo<div class="money-input"><b>€</b><input name="amount" required type="number" min="0.01" step="0.01" value="${suggested||''}" placeholder="0,00"></div></label><fieldset class="channel-choice"><legend>Da dove prendiamo la somma?</legend><label><input type="radio" name="channel" value="account" checked><span><b>Conto</b><small>Aggiorna il saldo del conto</small></span></label><label><input type="radio" name="channel" value="cash"><span><b>Contanti</b><small>Aggiorna i contanti disponibili</small></span></label></fieldset><p class="modal-copy">Il versamento aggiorna subito il capitale disponibile, il progresso e il ritmo di spesa.</p><p class="form-error" hidden></p><button class="button wide" type="submit">Registra versamento</button></form></div>`}

function advanceModal(){ const p=calculatePlan(state);return `<div class="modal-backdrop"><form class="modal" id="advance-form"><button class="close" type="button" data-close aria-label="Chiudi">×</button><span class="kicker">Scelta facoltativa</span><h2>Usare un anticipo?</h2><p class="modal-copy">Il piano non usa capitale per default. Puoi destinare al massimo ${money(p.maximumAdvance)}, oltre la riserva protetta di ${money(p.protectedCapital)}.</p><label>Importo dell’anticipo<div class="money-input"><b>€</b><input name="amount" type="number" min="0" max="${p.maximumAdvance}" step="1" value="${state.capitalAdvanceAmount||''}" placeholder="0"></div></label><label class="confirm-check"><input name="confirmed" type="checkbox" ${state.capitalAdvanceConfirmed?'checked':''}><span>Confermo di voler includere questo anticipo nel calcolo</span></label><p class="form-error" hidden>Inserisci un importo disponibile e conferma la scelta.</p><button class="button wide" type="submit">Applica anticipo</button>${state.useCapitalAdvance?'<button class="text-button remove-goal" type="button" data-clear-advance>Non usare capitale</button>':''}</form></div>`;}

function render(){ if(view==='onboarding') return onboarding(); if(view==='profile') return profileSetup(); app.innerHTML=view==='dashboard'?dashboard():view==='plan'?plan():view==='analysis'?analysis():transactions(); }

function submitDebtForm(form){
 const result=commitDebt({state,values:new FormData(form),persist:save,close:()=>form.closest('.modal-backdrop')?.remove(),recalculate:()=>{view='plan';render()},confirm:toast});
 if(!result.ok){const error=form.querySelector('.form-error');error.textContent=result.error;error.hidden=false}
 return result;
}

function submitRecurringForm(form){
 const result=commitRecurring({state,values:new FormData(form),persist:save,close:()=>form.closest('.modal-backdrop')?.remove(),recalculate:()=>{view='transactions';render()},confirm:toast});
 if(!result.ok){const error=form.querySelector('.form-error');error.textContent=result.error;error.hidden=false}
 return result;
}

function submitCapitalForm(form){
 const result=commitCapital({state,values:new FormData(form),persist:save});
 if(!result.ok){const error=form.querySelector('.form-error');error.textContent=result.error;error.hidden=false;return result}
 form.closest('.modal-backdrop')?.remove();render();toast(`Capitale aggiornato: ${money(result.total)}.`);return result;
}
function submitMovementForm(form){
 const fd=new FormData(form),amount=Number(fd.get('amount')),label=String(fd.get('label')||'').trim(),recordedAt=String(fd.get('recordedAt')||'');
 if(!amount||!label||!recordedAt){const error=form.querySelector('.form-error');error.textContent='Inserisci descrizione, data e un importo maggiore di zero.';error.hidden=false;form.querySelector(':invalid')?.focus();return false}
 const id=String(fd.get('id')||''),type=String(fd.get('type')),selectedRecurringId=type==='expense'?fd.get('expenseRecurringId'):fd.get('incomeRecurringId'),recurringItems=type==='expense'?state.expenses:state.incomes,normalize=value=>String(value||'').toLocaleLowerCase('it-IT').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,''),smartMatch=!selectedRecurringId?recurringItems.filter(item=>normalize(item.name)===normalize(label)||Math.abs((Number(item.amount)||0)-amount)<.01):[],recurringId=selectedRecurringId||smartMatch.length===1?String(selectedRecurringId||smartMatch[0].id):null,existing=state.transactions.find(x=>String(x.id)===id),chosenDate=new Date(`${recordedAt}T12:00:00`),today=new Date(),future=chosenDate>new Date(today.getFullYear(),today.getMonth(),today.getDate(),23,59,59);
 const transaction={id:existing?.id||Date.now(),label,amount,type,channel:fd.get('channel')==='cash'?'cash':'account',category:String(fd.get('category')||'Altro'),recurringId,recordedAt,date:future?'Programmata':chosenDate.toLocaleDateString('it-IT',{day:'numeric',month:'short'})};
 state.transactions=existing?state.transactions.map(x=>String(x.id)===id?transaction:x):[transaction,...state.transactions];syncSpendingEntry(transaction);save();form.closest('.modal-backdrop')?.remove();render();toast(existing?'Movimento aggiornato. Saldi ricalcolati.':'Movimento salvato. Saldi aggiornati.');return true;
}

document.addEventListener('click',e=>{
 const saveMovement=e.target.closest('[data-save-movement]');if(saveMovement){e.preventDefault();submitMovementForm(saveMovement.form);return}
 const saveDebt=e.target.closest('[data-save-debt]');if(saveDebt){e.preventDefault();submitDebtForm(saveDebt.form);return}
 const saveRecurring=e.target.closest('[data-save-recurring]');if(saveRecurring){e.preventDefault();submitRecurringForm(saveRecurring.form);return}
 const saveCapital=e.target.closest('[data-save-capital]');if(saveCapital){e.preventDefault();submitCapitalForm(saveCapital.form);return}
 const v=e.target.closest('[data-view]'); if(v){e.preventDefault();view=v.dataset.view;render();scrollTo(0,0);return}
 if(e.target.closest('[data-add]')){document.body.insertAdjacentHTML('beforeend',addChoiceModal());return}
 const occasional=e.target.closest('[data-add-occasional]');if(occasional){e.target.closest('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',modal(occasional.dataset.addOccasional));return}
 const editMovement=e.target.closest('[data-edit-movement]');if(editMovement){const transaction=state.transactions.find(x=>String(x.id)===editMovement.dataset.editMovement);if(transaction)document.body.insertAdjacentHTML('beforeend',modal(transaction.type,transaction));return}
 const removeMovement=e.target.closest('[data-remove-movement]');if(removeMovement){const transaction=state.transactions.find(x=>String(x.id)===removeMovement.dataset.removeMovement);if(transaction)document.body.insertAdjacentHTML('beforeend',removeMovementModal(transaction));return}
 const confirmRemoveMovement=e.target.closest('[data-confirm-remove-movement]');if(confirmRemoveMovement){const id=confirmRemoveMovement.dataset.confirmRemoveMovement;state.transactions=state.transactions.filter(x=>String(x.id)!==id);if(state.spendingPeriods[0])state.spendingPeriods[0].entries=state.spendingPeriods[0].entries.filter(x=>String(x.transactionId)!==id);save();e.target.closest('.modal-backdrop')?.remove();render();toast('Movimento eliminato. Saldi aggiornati.');return}
 const addRecurring=e.target.closest('[data-add-recurring]');if(addRecurring){e.target.closest('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',recurringModal(addRecurring.dataset.addRecurring));return}
 const editRecurring=e.target.closest('[data-edit-recurring]');if(editRecurring){const [type,id]=editRecurring.dataset.editRecurring.split(':');const items=type==='income'?state.incomes:state.expenses;const item=items.find(x=>String(x.id)===id);if(item)document.body.insertAdjacentHTML('beforeend',recurringModal(type,item));return}
 const removeRecurring=e.target.closest('[data-remove-recurring]');if(removeRecurring){const [type,id]=removeRecurring.dataset.removeRecurring.split(':');if(type==='income')state.incomes=state.incomes.filter(x=>String(x.id)!==id);else state.expenses=state.expenses.filter(x=>String(x.id)!==id);save();render();toast('Voce ricorrente rimossa. Budget aggiornato.');return}
 if(e.target.closest('[data-add-debt]')){document.body.insertAdjacentHTML('beforeend',debtModal());requestAnimationFrame(()=>document.querySelector('#debt-form input[name="name"]')?.focus({preventScroll:true}));return}
 if(e.target.closest('[data-goal]')){document.body.insertAdjacentHTML('beforeend',goalModal());return}
 if(e.target.closest('[data-accumulation]')){document.body.insertAdjacentHTML('beforeend',accumulationModal(e.target.closest('[data-accumulation]').dataset.accumulation));return}
 const contribute=e.target.closest('[data-contribute]');if(contribute){document.body.insertAdjacentHTML('beforeend',contributionModal(contribute.dataset.contribute,contribute.dataset.targetId));return}
 const selectPlan=e.target.closest('[data-select-plan]');if(selectPlan){state.selectedPlanId=selectPlan.dataset.selectPlan;comparingPlans=false;save();render();toast('Piano scelto. Potrai cambiarlo quando vuoi.');return}
 if(e.target.closest('[data-change-plan]')){comparingPlans=true;render();return}
 if(e.target.closest('[data-advance]')){document.body.insertAdjacentHTML('beforeend',advanceModal());return}
 if(e.target.closest('[data-clear-advance]')){state.useCapitalAdvance=false;state.capitalAdvanceConfirmed=false;state.capitalAdvanceAmount=0;save();e.target.closest('.modal-backdrop').remove();render();toast('Anticipo rimosso dal piano');return}
 if(e.target.closest('[data-clear-goal]')){state.goalEnabled=false;state.goalMonths=null;state.goalDate=null;save();e.target.closest('.modal-backdrop').remove();render();toast('Obiettivo rimosso');return}
 if(e.target.closest('[data-clear-accumulation]')){const id=e.target.closest('[data-clear-accumulation]').dataset.clearAccumulation;state.accumulationPlans=state.accumulationPlans.filter(item=>String(item.id)!==String(id));save();e.target.closest('.modal-backdrop').remove();render();toast('Piano di accumulo rimosso');return}
 const editDebt=e.target.closest('[data-edit-debt]');if(editDebt){const debt=state.debts.find(x=>String(x.id)===editDebt.dataset.editDebt);if(debt){document.body.insertAdjacentHTML('beforeend',debtModal(debt));requestAnimationFrame(()=>document.querySelector('#debt-form input[name="name"]')?.focus({preventScroll:true}))}return}
 const removeDebt=e.target.closest('[data-remove-debt]');if(removeDebt){const debt=state.debts.find(x=>String(x.id)===removeDebt.dataset.removeDebt);if(debt)document.body.insertAdjacentHTML('beforeend',removeDebtModal(debt));return}
 const confirmRemove=e.target.closest('[data-confirm-remove]');if(confirmRemove){state.debts=state.debts.filter(x=>String(x.id)!==confirmRemove.dataset.confirmRemove);save();document.querySelector('.modal-backdrop')?.remove();render();toast('Debito rimosso');return}
 if(e.target.closest('[data-settings]')){document.body.insertAdjacentHTML('beforeend',settingsModal());return}
 if(e.target.closest('[data-install-app]')){if(deferredInstallPrompt){deferredInstallPrompt.prompt();deferredInstallPrompt.userChoice.then(()=>{deferredInstallPrompt=null});}else{toast(/iphone|ipad|ipod/i.test(navigator.userAgent)?'In Safari: Condividi, poi Aggiungi alla schermata Home.':'Per installare serve la versione pubblicata con HTTPS.');}return}
 if(e.target.closest('[data-reset-all]')){e.target.closest('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',resetAllModal());return}
 if(e.target.closest('[data-confirm-reset]')){localStorage.removeItem('rientro-state');state=freshState();view='onboarding';onboardingStep=0;document.querySelector('.modal-backdrop')?.remove();render();toast('Dati cancellati. Ripartiamo da zero.');return}
 if(e.target.closest('[data-capital]')){e.target.closest('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',capitalModal());return}
 if(e.target.closest('[data-close]')||e.target.classList.contains('modal-backdrop')) e.target.closest('.modal-backdrop')?.remove();
 if(e.target.closest('[data-back]')){onboardingStep--;render();}
 const choice=e.target.closest('[data-choose]');if(choice){const p=calculatePlan(state);state.targetMonths=choice.dataset.choose==='longer'?p.suggestedMonths:Math.ceil(p.debtTotal/Math.max(50,p.sustainable-60));state.mode='common';save();render();toast('Alternativa applicata al piano');}
});

document.addEventListener('submit',e=>{
 e.preventDefault(); const fd=new FormData(e.target);
 if(e.target.id==='movement-form'){
  submitMovementForm(e.target);return;
 }
 if(e.target.id==='recurring-form'){
  submitRecurringForm(e.target);return;
 }
 if(e.target.id==='capital-form'){submitCapitalForm(e.target);return}
 if(e.target.id==='debt-form'){
  submitDebtForm(e.target);return;
 }
 if(e.target.id==='goal-form'){
  const goalMonths=Number(fd.get('goalMonths'))||null;const goalDate=String(fd.get('goalDate')||'')||null;if(!goalMonths&&!goalDate){e.target.querySelector('.form-error').hidden=false;return}
  state.goalEnabled=true;state.goalMonths=goalMonths;state.goalDate=goalDate;save();e.target.closest('.modal-backdrop').remove();render();toast('Obiettivo valutato');return;
 }
 if(e.target.id==='accumulation-form'){
  const id=String(fd.get('id')||''),name=String(fd.get('name')||'').trim(),target=Number(fd.get('target')),months=Number(fd.get('months')),priority=Number(fd.get('priority'))||1;if(!name||target<=0||months<=0){e.target.querySelector('.form-error').hidden=false;return}
  const existing=state.accumulationPlans.find(item=>String(item.id)===id),item={id:existing?.id||Date.now(),name,target,months,priority,current:Math.min(target,Number(existing?.current)||0)};state.accumulationPlans=existing?state.accumulationPlans.map(plan=>String(plan.id)===id?item:plan):[...state.accumulationPlans,item];save();e.target.closest('.modal-backdrop').remove();render();toast(existing?'Obiettivo aggiornato':'Piano di accumulo creato e incluso nel budget');return;
 }
 if(e.target.id==='contribution-form'){
  const result=applyPlanContribution(state,{kind:String(fd.get('kind')),targetId:String(fd.get('targetId')||''),amount:Number(fd.get('amount')),channel:String(fd.get('channel'))});if(!result.ok){const error=e.target.querySelector('.form-error');error.textContent=result.error;error.hidden=false;return}
  save();e.target.closest('.modal-backdrop').remove();render();toast(`${result.transaction.planKind==='debt'?'Pagamento':'Versamento'} registrato. Saldi e progresso aggiornati.`);return;
 }
 if(e.target.id==='advance-form'){
  const p=calculatePlan({...state,useCapitalAdvance:false,capitalAdvanceConfirmed:false});const amount=Number(fd.get('amount'));const confirmed=fd.get('confirmed')==='on';if(!confirmed||amount<=0||amount>p.maximumAdvance){e.target.querySelector('.form-error').hidden=false;return}
  state.useCapitalAdvance=true;state.capitalAdvanceConfirmed=true;state.capitalAdvanceAmount=amount;save();e.target.closest('.modal-backdrop').remove();render();toast('Anticipo confermato e separato dalle rate');return;
 }
 if(e.target.id==='profile-form' || e.target.id==='settings-form'){
  state.name=String(fd.get('name')).trim(); if(!state.name)return;
  if(e.target.id==='profile-form'){const capitalResult=commitCapital({state,values:fd});if(!capitalResult.ok){const error=e.target.querySelector('.form-error');error.textContent=capitalResult.error;error.hidden=false;return}state.profileConfigured=true;view='dashboard';save();render();toast('Profilo e capitale aggiornati.');return}
  state.profileConfigured=true;save();e.target.closest('.modal-backdrop').remove();render();toast('Nome aggiornato');return;
 }
 if(e.target.id==='onboarding-form'){
  const name=String(fd.get('name')).trim();if(!name)return;
  state.name=name;state.profileConfigured=true;state.onboarded=true;state.logicVersion=2;view='dashboard';save();render();toast('Profilo creato. Ora aggiungi solo ciò che ti serve.');
 }
});

document.addEventListener('change',e=>{if(e.target.matches('#movement-form input[name="type"]')){const label=e.target.form.querySelector('[data-channel-account]');if(label)label.textContent=e.target.value==='income'?'Bonifico o accredito':'Bancomat o carta';e.target.form.classList.toggle('is-income',e.target.value==='income');}});

render();

window.addEventListener('beforeinstallprompt', event => { event.preventDefault(); deferredInstallPrompt = event; });
if ('serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(registration=>registration.update()).catch(() => {}));
